          },
          "then": {
            "properties": {
              "readLaterAddedAt": {
                "type": "null"
              },
              "readAt": {
                "type": "null"
              }
            }
          }
        },
        {
          "if": {
            "properties": {
              "readLaterState": {
                "const": "unread"
              }
            }
          },
          "then": {
            "required": [
              "readLaterAddedAt",
              "readAt"
            ],
            "properties": {
              "readLaterAddedAt": {
                "type": "string",
                "format": "date-time"
              },
              "readAt": {
                "type": "null"
              }
            }
          }
        },
        {
          "if": {
            "properties": {
              "readLaterState": {
                "const": "read"
              }
            }
          },
          "then": {
            "required": [
              "readLaterAddedAt",
              "readAt"
            ],
            "properties": {
              "readLaterAddedAt": {
                "type": "string",
                "format": "date-time"
              },
              "readAt": {
                "type": "string",
                "format": "date-time"
              }
            }
          }
        },
        {
          "if": {
            "properties": {
              "archived": {
                "const": false
              }
            }
          },
          "then": {
            "properties": {
              "archivedAt": {
                "type": "null"
              }
            }
          }
        },
        {
          "if": {
            "properties": {
              "archived": {
                "const": true
              }
            }
          },
          "then": {
            "required": [
              "archivedAt"
            ],
            "properties": {
              "archivedAt": {
                "type": "string",
                "format": "date-time"
              }
            }
          }
        }
      ]
    },
