const fs = require('fs');
const text = fs.readFileSync('specs/001-bookmark-manager/tasks.md', 'utf8');
const lines = text.split(/\r?\n/);
const tasks = lines.filter(line => line.startsWith('- [ ]'));
const re = /^- \[ \] T(\d{3})(?: \[P\])?(?: \[US[1-5]\])? .+\S$/;
const malformed = tasks.filter(line => !re.test(line));
const ids = tasks.map(line => Number(line.match(/^\- \[ \] T(\d{3})/)[1]));
const expected = Array.from({length: ids.length}, (_, i) => i + 1);
const sequenceOk = ids.every((id, i) => id === expected[i]);
const counts = {setup: 0, US1: 0, US2: 0, US3: 0, US4: 0, US5: 0, polish: 0};
for (const line of tasks) {
  const story = line.match(/\[(US[1-5])\]/)?.[1];
  if (story) counts[story]++;
  else if (Number(line.match(/T(\d{3})/)[1]) <= 7) counts.setup++;
  else if (Number(line.match(/T(\d{3})/)[1]) <= 23) counts.setup++;
  else counts.polish++;
}
const parallel = tasks.filter(line => line.includes('[P]')).length;
console.log(JSON.stringify({total: tasks.length, malformed, sequenceOk, first: ids[0], last: ids.at(-1), counts, parallel}, null, 2));
if (malformed.length || !sequenceOk || ids[0] !== 1 || ids.at(-1) !== tasks.length) process.exit(1);
