import type { BookmarkRepository } from '../repositories/bookmark-repository.js';
import { SESSION_COOKIE } from '../security/session.js';

function userId(request:FastifyRequest,reply:FastifyReply,auth:AuthService){const user=auth.authenticate(request.cookies[SESSION_COOKIE]);if(!user){reply.code(401).send({error:{code:'UNAUTHORIZED',message:'Sign in to continue.'}});return;}return user.id;}
const respondError=(error:unknown,reply:FastifyReply)=>{if(error instanceof BookmarkServiceError)return reply.code(error.status).send({error:{code:error.code,message:error.message,existingId:error.existingId}});throw error;};
export async function bookmarkRoutes(app:FastifyInstance,auth:AuthService,service:BookmarkService,repository:BookmarkRepository){
  app.get('/api/v1/bookmarks',(request:any,reply)=>{const user=userId(request,reply,auth);if(!user)return;const q=request.query??{};try{return service.list(user,{scope:q.scope,q:q.q,tags:Array.isArray(q.tag)?q.tag:q.tag?[q.tag]:[],favorite:q.favorite===undefined?undefined:q.favorite==='true',readLaterState:q.readLaterState,sort:q.sort,direction:q.direction,limit:q.limit?Number(q.limit):undefined,offset:q.offset?Number(q.offset):undefined});}catch(error){return respondError(error,reply);}});
  app.post('/api/v1/bookmarks',(request:any,reply)=>{const user=userId(request,reply,auth);if(!user)return;try{return reply.code(201).send(service.create(user,request.body??{}));}catch(error){return respondError(error,reply);}});
  app.get('/api/v1/bookmarks/:id',(request:any,reply)=>{const user=userId(request,reply,auth);if(!user)return;try{return service.get(user,request.params.id);}catch(error){return respondError(error,reply);}});
  app.patch('/api/v1/bookmarks/:id',(request:any,reply)=>{const user=userId(request,reply,auth);if(!user)return;try{return service.update(user,request.params.id,request.body??{});}catch(error){return respondError(error,reply);}});
  app.delete('/api/v1/bookmarks/:id',(request:any,reply)=>{const user=userId(request,reply,auth);if(!user)return;try{service.delete(user,request.params.id);return reply.code(204).send();}catch(error){return respondError(error,reply);}});
  app.get('/api/v1/bookmarks/:id/icon',(request:any,reply)=>{const user=userId(request,reply,auth);if(!user)return;const icon=repository.icon(user,request.params.id);if(!icon)return reply.code(404).send({error:{code:'NOT_FOUND',message:'Icon not found.'}});return reply.header('content-type','image/png').header('cache-control','private, max-age=86400').send(Buffer.from(icon.data));});
}

