import { useEffect, useId, useState, type KeyboardEvent } from 'react';
import { suggestTags, type Tag } from './bookmark-api';

export function TagCombobox({value,onChange}:{value:string[];onChange:(tags:string[])=>void}){const[input,setInput]=useState('');const[suggestions,setSuggestions]=useState<Tag[]>([]);const[active,setActive]=useState(-1);const id=useId();
  useEffect(()=>{let live=true;if(!input.trim()){setSuggestions([]);return;}const timer=setTimeout(()=>void suggestTags(input).then(r=>live&&setSuggestions(r.items)).catch(()=>live&&setSuggestions([])),180);return()=>{live=false;clearTimeout(timer);};},[input]);
  const add=(name:string)=>{const clean=name.trim();if(clean&&!value.some(v=>v.toLocaleLowerCase()===clean.toLocaleLowerCase()))onChange([...value,clean]);setInput('');setSuggestions([]);setActive(-1);};
  const key=(event:KeyboardEvent<HTMLInputElement>)=>{if(event.key==='ArrowDown'){event.preventDefault();setActive(v=>Math.min(v+1,suggestions.length-1));}else if(event.key==='ArrowUp'){event.preventDefault();setActive(v=>Math.max(v-1,0));}else if(event.key==='Enter'){event.preventDefault();add(active>=0?suggestions[active]!.name:input);}else if(event.key===',' ){event.preventDefault();add(input);}};
  return <div className="tag-field"><label htmlFor={id}>Tags</label><div className="tag-input">{value.map(tag=><span className="tag-chip" key={tag}>{tag}<button type="button" aria-label={`Remove ${tag}`} onClick={()=>onChange(value.filter(v=>v!==tag))}>×</button></span>)}<input id={id} value={input} onChange={e=>setInput(e.target.value)} onKeyDown={key} role="combobox" aria-expanded={suggestions.length>0} aria-controls={`${id}-list`} aria-activedescendant={active>=0?`${id}-${active}`:undefined} placeholder={value.length?'Add another…':'Type to reuse or create tags…'} /></div>{suggestions.length>0&&<ul id={`${id}-list`} role="listbox" className="suggestions">{suggestions.map((tag,index)=><li id={`${id}-${index}`} role="option" aria-selected={index===active} key={tag.id}><button type="button" onClick={()=>add(tag.name)}>{tag.name}</button></li>)}</ul>}</div>;
}

