u restore or delete them.':'Paste a link and Keepmark will collect its title, summary, and icon for you.'}</p>{isFiltered&&<a href="/">Clear search and filters</a>}{scope==='active'&&!isFiltered&&<button className="primary" onClick={()=>setAdding(true)}>Save a link</button>}</section>}<section className="bookmark-list" aria-label="Bookmarks">{data.items.map(item=><BookmarkCard bookmark={item} onChanged={()=>void data.reload()} key={item.id}/>)}</section></main>}

