import type { Database } from '../../db/database.js';
import type { Backup, BackupBookmark } from './backup-format.js';
const html=(value:string)=>value.replaceAll('&','&amp;').replaceAll('<','&lt;').replaceAll('>','&gt;').replaceAll('"','&quot;');
export class ExportService{constructor(private db:Database){}complete(userId:string):Backup{const rows=this.db.prepare('SELECT * FROM bookmarks WHERE user_id=? ORDER BY created_at,id').all(userId) as any[];const bookmarks:BackupBookmark[]=rows.map(row=>{const tags=(this.db.prepare('SELECT t.name FROM tags t JOIN bookmark_tags bt ON bt.tag_id=t.id WHERE bt.bookmark_id=? ORDER BY t.name COLLATE NOCASE').all(row.id) as any[]).map(t=>t.name);const icon=this.db.prepare('SELECT data,width,height FROM bookmark_icons WHERE user_id=? AND bookmark_id=?').get(userId,row.id) as any;return{exportId:row.id,url:row.url,title:row.title,description:row.description,notes:row.notes,tags,favorite:Boolean(row.is_favorite),readLaterState:row.read_later_state,readLaterAddedAt:row.read_later_added_at,readAt:row.read_at,archived:Boolean(row.archived_at),archivedAt:row.archived_at,icon:icon?{mediaType:'image/png',dataBase64:Buffer.from(icon.data).toString('base64'),width:icon.width,height:icon.height}:null,createdAt:row.created_at,updatedAt:row.updated_at};});return{format:'bookmark-manager-backup',schemaVersion:1,exportedAt:new Date().toISOString(),bookmarks};}
  browser(userId:string){const backup=this.complete(userId);const groups=new Map<string,BackupBookmark[]>();for(const bookmark of backup.bookmarks){const group=bookmark.tags[0]??(bookmark.archived?'Archived':'Bookmarks');groups.set(group,[...(groups.get(group)??[]),bookmark]);}let content='<!DOCTYPE NETSCAPE-Bookmark-file-1>
<META HTTP-EQUIV="Content-Type" CONTENT="text/html; charset=UTF-8">
<TITLE>Keepmark Bookmarks</TITLE>
<H1>Keepmark Bookmarks</H1>
<DL><p>
';for(const[group,items]of groups){content+=`  <DT><H3>${html(group)}</H3>
  <DL><p>
`;for(const item of items)content+=`    <DT><A HREF="${html(item.url)}" ADD_DATE="${Math.floor(Date.parse(item.createdAt)/1000)}">${html(item.title)}</A>
`;content+='  </DL><p>
';}return content+'</DL><p>
';}}

